-- ===========================================================================
-- FX Partners — directory update: logos, cleaned links, and more listings
-- ===========================================================================
-- Run AFTER seed_external_brokers.sql. Safe to re-run. Unverified external
-- data only: never writes the review-based rating, reviews_count, or the
-- verified licenses.
-- ===========================================================================

begin;

-- 1) Logos for the original brokers (they had none). XM from Wikimedia Commons,
--    Vantage from the directory import, the rest from each official domain's
--    site icon. Only fills an empty logo — never replaces one set by an admin.
update public.brokers set logo_url = v.logo
from (values
  ('xm',       'https://upload.wikimedia.org/wikipedia/commons/5/5b/XM_logo.png'),
  ('vantage',  'https://d3kvcd8uuqwmxt.cloudfront.net/filecache/broker_logo/vantagefx.png_148_62bede5a6d7bd9.14103271.png'),
  ('oneroyal', 'https://www.google.com/s2/favicons?sz=128&domain=oneroyal.com'),
  ('inzo',     'https://www.google.com/s2/favicons?sz=128&domain=inzo.co'),
  ('tnfx',     'https://www.google.com/s2/favicons?sz=128&domain=tnfx.co')
) as v(slug, logo)
where public.brokers.slug = v.slug and coalesce(public.brokers.logo_url, '') = '';

-- 2) Strip query strings / fragments from every "official site" link. 47 of the
--    imported links carried another party's referral code (e.g. ?ref=IB_FxList,
--    ?aff=..., ?ib=...), which would have credited them for our visitors.
update public.brokers
set external_data = jsonb_set(external_data, '{website_url}',
      to_jsonb(regexp_replace(external_data->>'website_url', '[?#].*$', '')))
where external_data ? 'website_url' and external_data->>'website_url' ~ '[?#]';

-- 3) Enrich 21 existing brokers with the second directory's data. Existing
--    values win: a score is only filled where missing, and new keys are added
--    without overwriting ones already present.
update public.brokers b set
  external_score  = coalesce(b.external_score, v.score),
  external_source = coalesce(b.external_source, 'directory'),
  external_data   = v.data || coalesce(b.external_data, '{}'::jsonb),
  logo_url        = coalesce(nullif(b.logo_url, ''), v.logo)
from (values
  ('avatrade', 9.5::numeric, '{"regulation_country": "أستراليا", "business_model": "صناعة السوق (MM)", "years": "15-20 سنة", "account_type": "ECN", "platforms": "MetaTrader 4"}'::jsonb, 'https://eimgjys.fxeyee.com/logo/638524966565554499/FXT638524966565554499_113163.png_wiki-template-global'),
